package com.company.logicdelete.analyzer;

import com.fasterxml.jackson.databind.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;

final class CoverageAnalyzer {
    void run(Path affected,Path runtime,Path output)throws IOException{Set<String>a=readIds(affected),seen=new TreeSet<>();ObjectMapper om=new ObjectMapper();try(BufferedReader r=Files.newBufferedReader(runtime,StandardCharsets.UTF_8)){String line;while((line=r.readLine())!=null)try{JsonNode n=om.readTree(line);if(n.hasNonNull("sqlId"))seen.add(n.get("sqlId").asText());}catch(Exception ignored){}}Set<String>covered=new TreeSet<>(a);covered.retainAll(seen);Set<String>uncovered=new TreeSet<>(a);uncovered.removeAll(seen);Files.createDirectories(output);writeList(output.resolve("covered-sql-ids.csv"),covered);writeList(output.resolve("uncovered-sql-ids.csv"),uncovered);writeList(output.resolve("runtime-sql-ids.csv"),seen);double rate=a.isEmpty()?0:(100.0*covered.size()/a.size());Files.write(output.resolve("coverage-summary.csv"),("affectedSqlCount,runtimeSqlCount,coveredSqlCount,uncoveredSqlCount,coverageRate\n"+a.size()+","+seen.size()+","+covered.size()+","+uncovered.size()+","+String.format(Locale.ROOT,"%.2f%%",rate)+"\n").getBytes(StandardCharsets.UTF_8));String html="<!doctype html><meta charset=utf-8><title>Coverage report</title><h1>Logic delete SQL coverage</h1><p>Covered "+covered.size()+" / "+a.size()+" ("+String.format(Locale.ROOT,"%.2f%%",rate)+")</p><h2>Uncovered</h2><ul><li>"+String.join("</li><li>",uncovered)+"</li></ul>";Files.write(output.resolve("coverage-report.html"),html.getBytes(StandardCharsets.UTF_8));}
    private Set<String>readIds(Path p)throws IOException{Set<String>s=new TreeSet<>();for(String x:Files.readAllLines(p,StandardCharsets.UTF_8))if(!x.trim().isEmpty())s.add(x.trim());return s;}private void writeList(Path p,Set<String>s)throws IOException{List<String>l=new ArrayList<>();l.add("fullSqlId");for(String x:s)l.add(ReportWriter.csv(x));Files.write(p,l,StandardCharsets.UTF_8);}
}
